CAT = "zapsiraAccess"; SEG = "ACC"
# Access control, searching and key control: standard guarding practice for Grade E and D posts,
# with the Constitution s. 14 (privacy) and the Protection of Personal Information Act 4 of 2013
# for visitor records.
Q = [
('What is the main purpose of a boom gate at an estate entrance?',
 'To stop cars until cleared', ['To measure car speeds', 'To collect toll fees', 'To shade the guardhouse'],
 'A boom holds each vehicle at the gate until the officer has checked and recorded it and the visit is confirmed.'),
('A visitor arrives at an office park gate. What should the officer do before letting the visitor in?',
 'Confirm with the host', ['Wave them through politely', 'Let them find the host', 'Ask another visitor to vouch'],
 'The officer checks identity, records the visit and confirms with the person being visited before granting access.'),
('How much personal information should a visitor register collect?',
 'Only what the site needs', ['As much as possible', "Every visitor's salary", 'Details of their family'],
 'The Protection of Personal Information Act requires personal information to be adequate, relevant and not excessive for its purpose.'),
("Why should visitor register entries be kept away from other visitors' view?",
 'They hold personal data', ['They are badly written', 'Visitors might copy the format', 'They are only drafts'],
 'The Protection of Personal Information Act requires personal information to be kept secure. A register left open lets others read names, ID numbers and phone numbers.'),
('A person follows closely behind an employee through a turnstile without swiping a card. What is this called?',
 'Tailgating', ['Clocking in', 'Escorting', 'Signing in'],
 "Tailgating (piggybacking) is entering behind an authorised person without using one's own access. Stop the person politely and process them properly."),
('An employee says she forgot her access card at home. What should the officer do?',
 'Verify her, issue a day pass', ['Let her in without a record', 'Send her home for the day', "Lend her a colleague's card"],
 'Following site procedure, the officer confirms her identity with a supervisor or list, records it and issues a day pass. Cards are never shared.'),
("A contractor's access card shows a photo of someone else. What should the officer do?",
 'Refuse entry and report it', ['Let him in, the card works', 'Keep quiet to avoid trouble', 'Take a photo and wave him in'],
 'A card in the wrong hands is a security breach. Deny access, keep the card if site rules say so and report it to the supervisor.'),
('A delivery truck arrives at a warehouse. What should the gate officer check first?',
 'The delivery note', ["The driver's music choice", "Only the truck's colour", "The driver's home suburb"],
 'Delivery documents are checked against what is expected. The registration, driver, times and seal numbers are recorded.'),
('A truck leaves a warehouse. Why does the officer compare the seal number on the doors with the gate pass?',
 'To show it was not opened', ["To count the truck's tyres", "To check the driver's licence", 'To measure fuel use'],
 'A matching, intact seal shows the load has not been tampered with since it was sealed. A broken or different seal is reported before the truck leaves.'),
('When searching a person with consent, who should ideally do the body search?',
 'A same-gender officer', ['The most senior officer', 'Any officer who is nearby', 'A visitor who volunteers'],
 'Same-gender searching respects dignity and privacy and protects the officer from complaints. Search in view of a witness where possible.'),
('During a consented bag search, what is the best way to search?',
 'Ask the owner to open it', ['Tip it out on the floor', 'Put your hands in quickly', 'Take the bag to a back room'],
 'Asking the owner to open and show the contents respects dignity and reduces the risk of injury from sharp objects.'),
('What does a key register record?',
 'Who took which key, when', ['The price of each lock', 'The colour of each key ring', 'Only keys that were lost'],
 "A key register logs each key's issue and return, the person's name and signature, and times, so every key can be accounted for."),
('At the end of a shift a master key is missing from the key cabinet. What should the officer do?',
 'Report it at once', ['Wait to see if it comes back', 'Cut a copy quietly', 'Write it off as lost'],
 'A missing master key compromises the whole site. Report it immediately so the supervisor can trace it or change locks.'),
('A contractor asks to borrow the server room key for an hour. What is the correct procedure?',
 'Check authority, sign it out', ['Hand it over to be helpful', 'Give him a spare copy', 'Tell him where it hangs'],
 'Keys to sensitive areas are issued only to authorised people, signed out in the key register and signed back in.'),
('A visitor says he is a municipal inspector and must enter right away. What should the officer do?',
 'Check his ID and call the host', ['Let him in, he is official', 'Refuse all officials', 'Ask him to wait in the car park forever'],
 'Officials still identify themselves. Check the identification card, record it and contact the responsible person before granting access.'),
('Why should an officer escort a visitor into a restricted area?',
 'To control where they go', ['To carry their bags', 'To make conversation', 'To check their shoes are clean'],
 'An escort stops a visitor from wandering into areas they are not authorised to see and helps if there is an emergency.'),
('A car arrives at an estate boom gate. The driver says he is visiting a resident but does not know the house number. What is best?',
 'Confirm with the resident', ['Open the boom for him', 'Tell him to guess the house', 'Let him drive around to look'],
 "Entry is granted only once the resident confirms the visit through the estate's procedure, such as a call or an app code."),
('A worker leaving a factory carries a laptop. What document should the officer ask for?',
 'A signed property pass', ['A car licence disc', "A doctor's sick note", 'A copy of a payslip'],
 'A property removal or gate pass signed by an authorised manager shows the item may leave the site. Without it, the item stays and the supervisor is informed.'),
("What should an officer do with a visitor's pass when the visitor leaves?",
 'Collect it, log the time', ['Let the visitor keep it', 'Throw it away', 'Give it to the next visitor unchecked'],
 'Collecting passes stops them being reused and closes the record, so the register shows who is still on site.'),
('At closing time the register shows two visitors still signed in. What should the officer do?',
 'Check if they are still in', ['Assume they have left', 'Delete the open entries', 'Lock all doors at once'],
 'Unclosed entries may mean people are still inside. Confirm with the hosts or search the area so nobody is locked in and no intruder is hiding.'),
("Why is it risky to let one person 'sign in' a group of ten visitors under one name?",
 'Each must be identified', ['It uses less paper', 'It is quicker for everyone', 'The group might be late'],
 'In an evacuation or incident the site must know exactly who is inside. Each visitor is recorded separately.'),
('A courier wants to deliver a parcel straight to an office upstairs. What is the usual safer practice?',
 'Receive it at reception', ['Send him up alone', 'Open the parcel at the gate', 'Refuse all parcels'],
 'Receiving parcels at a controlled point and calling the recipient keeps unknown people out of the building.'),
('Why should an officer check under and inside a vehicle at a high-security site?',
 'To find hidden people or goods', ['To admire the car', 'To check its service history', 'To test that the hooter works'],
 'Vehicle checks look for concealed people, stolen goods or prohibited items, using a mirror under the vehicle and with the driver opening the boot.'),
("A resident asks the gate officer to let a friend in using the resident's own remote. What should happen?",
 'Follow the visitor procedure', ['Let the friend use the remote', 'Lift the boom for all friends', 'Log the remote as lost'],
 "Visitors are processed through the gate procedure, not let in on a resident's own access device."),
('Which of these is a physical access control measure?',
 'A turnstile', ['A staff newsletter', 'A tea break roster', 'A parking survey'],
 'Turnstiles, booms, gates, locks and fences physically control who can pass. People and procedures make them work.'),
('An access card reader at the staff entrance stops working. What should the officer do?',
 'Check entry by hand, report it', ['Wedge the door open', 'Close the entrance for the day', 'Let anyone through until it is fixed'],
 'The officer checks each person by hand against cards or lists, records entries and reports the fault so it can be repaired.'),
('A person in overalls carries a ladder toward the roof saying he is fixing an aerial. Nobody told you. What should you do?',
 'Stop him and check first', ['Hold the ladder for him', 'Assume he is genuine', 'Ignore it, it is daytime'],
 'Uniforms and tools are easy to fake. Unexpected work is confirmed with the client or facilities manager before access is given.'),
('A visitor refuses to give any identification at a site where it is required. What should the officer do?',
 'Politely refuse entry', ['Take the ID by force', 'Let them in this once', 'Arrest the visitor'],
 'Giving identification is a condition of entry. A visitor who will not comply is refused entry politely and the refusal is recorded.'),
]
